package io.joshuasalcedo.swaswa.ui.layout;

import io.joshuasalcedo.swaswa.html.Node;
import io.joshuasalcedo.swaswa.html.PageScript;
import io.joshuasalcedo.swaswa.html.Text;
import io.joshuasalcedo.swaswa.react.ReactElement;
import io.joshuasalcedo.swaswa.ui.Ui;
import java.util.List;

/**
 * swaswa-ui's {@code Card} (more-layout.tsx), a real React component, from Java: create it, set it, add it.
 * Generated by swaswa-react java-gen from its TypeScript props: do not edit.
 */
public final class UiCard extends ReactElement<UiCard> {

    /** A UiCard. */
    public UiCard() {
        super("Card", true);
    }

    /** A UiCard showing {@code text}. */
    public UiCard(String text) {
        this();
        add(new Text(text));
    }

    /** A UiCard holding {@code children}: its children, where it shows them. */
    public UiCard(Node... children) {
        this();
        for (Node child : children) add(child);
    }

    /** {@code name}. */
    public UiCard setName(String value) {
        return prop("name", value);
    }

    public String getName() {
        return getProp("name", String.class);
    }

    @Override
    protected List<PageScript> libraries() {
        return List.of(Ui.bundle());
    }
}
